// c3 package executor: YUV/YCbCr sampling-format and layout conversions
// (nppi_color_conversion.h, docs/agent_packages/c3.md).
//
// Host-visible surface (plain .cpp translation units): entry points are
// declared here and defined in nppi_c3_yuv_layout_executor.cu.  The public
// API wrappers are generated by mpp_scripts/gen_family.py from
// mpp_scripts/families/nppi_c3_*.json.
//
// Semantics baseline: NVIDIA NPP 13.4 (RTX 5090), measured with probe
// programs and locked in by test/unit/diff/test_nppi_c3_yuv_layout_generated.cpp:
//   * YCbCr 4:2:2 packed C2 rows are [Y0 Cb Y1 Cr]; CbYCr422 rows are
//     [Cb Y0 Cr Y1] (selected with `swap`).
//   * P3 is three planes (Y, Cb, Cr); a YCrCb family reads/writes the
//     chroma planes in the opposite order.
//   * P2 is a Y plane plus one interleaved CbCr plane (Cb,Cr pairs).
//   * Subsampling is pure decimation (never averaging): 4:2:0 keeps even
//     source rows, 4:1:1 keeps every second chroma column (every 4th pixel).
//   * NVIDIA quirk: 4:1:1 -> 4:2:0 interleaves the two source chroma rows
//     into one destination row at x = 2*c + (y & 1); reproduced bit-exactly.
#ifndef NPPI_C3_YUV_LAYOUT_EXECUTOR_H
#define NPPI_C3_YUV_LAYOUT_EXECUTOR_H

#include "npp.h"
#include <cuda_runtime.h>

namespace nppi {
namespace c3yuv {

// --- packed C2 -> planar P3 ------------------------------------------------
// px / py: chroma decimation factors relative to the packed pair grid
// (px = 2 for 4:1:1, py = 2 for 4:2:0).  layoutSrc selects the packed row
// layout: 0 = YCbCr422 [Y0 Cb Y1 Cr], 1 = YCrCb422 [Y0 Cr Y1 Cb],
// 2 = CbYCr422 [Cb Y0 Cr Y1].  swapDst writes (Cr, Cb) instead of (Cb, Cr).
NppStatus c2ToP3(const Npp8u *pSrc, int nSrcStep, Npp8u *pDst[3], const int aDstStep[3], NppiSize oSizeROI,
                 cudaStream_t stream, int layoutSrc, int px, int py, int swapDst);

// --- packed C2 -> planar Y + interleaved CbCr (P2) -------------------------
NppStatus c2ToP2(const Npp8u *pSrc, int nSrcStep, Npp8u *pDstY, int nDstYStep, Npp8u *pDstCbCr, int nDstCbCrStep,
                 NppiSize oSizeROI, cudaStream_t stream, int layoutSrc, int px, int py);

// --- planar P3 -> packed C2 ----------------------------------------------
// srcMode: 0 = 4:2:2 chroma plane (one sample per pair),
//          1 = 4:1:1 chroma plane (one sample per four pixels),
//          2 = 4:2:0 chroma plane (decimated rows).
NppStatus p3ToC2(const Npp8u *const pSrc[3], const int aSrcStep[3], Npp8u *pDst, int nDstStep, NppiSize oSizeROI,
                 cudaStream_t stream, int swapSrc, int srcMode, int swapDst);

// --- planar Y + interleaved 4:1:1 CbCr -> packed C2 4:2:2 -----------------
NppStatus p2ToC2_411(const Npp8u *pSrcY, int nSrcYStep, const Npp8u *pSrcCbCr, int nSrcCbCrStep, Npp8u *pDst,
                     int nDstStep, NppiSize oSizeROI, cudaStream_t stream, int swapDst);

// --- planar Y + interleaved CbCr 4:1:1 -> planar P3 4:1:1 ----------------
NppStatus p2ToP3_411(const Npp8u *pSrcY, int nSrcYStep, const Npp8u *pSrcCbCr, int nSrcCbCrStep, Npp8u *pDst[3],
                     const int aDstStep[3], NppiSize oSizeROI, cudaStream_t stream);

// --- planar Y + interleaved 4:1:1 CbCr -> planar P3 4:2:2 (replicated) ---
NppStatus p2ToP3_422(const Npp8u *pSrcY, int nSrcYStep, const Npp8u *pSrcCbCr, int nSrcCbCrStep, Npp8u *pDst[3],
                     const int aDstStep[3], NppiSize oSizeROI, cudaStream_t stream);

// --- planar P3 4:1:1 -> planar Y + interleaved CbCr 4:1:1 ----------------
NppStatus p3ToP2_411(const Npp8u *const pSrc[3], const int aSrcStep[3], Npp8u *pDstY, int nDstYStep,
                     Npp8u *pDstCbCr, int nDstCbCrStep, NppiSize oSizeROI, cudaStream_t stream);

// --- packed C2 reorder (YCbCr422 <-> YCrCb422 <-> CbYCr422) ---------------
// layout ids as for c2ToP3.
NppStatus c2Reorder(const Npp8u *pSrc, int nSrcStep, Npp8u *pDst, int nDstStep, NppiSize oSizeROI,
                    cudaStream_t stream, int layoutSrc, int layoutDst);

// --- planar chroma resampling between sampling formats --------------------
// mode: 0 = 4:1:1 -> 4:2:2 (replicate each chroma sample twice)
//       1 = 4:2:2 -> 4:1:1 (keep every second chroma column)
//       2 = 4:2:2 -> 4:2:0 (keep even rows)
//       3 = 4:2:0 -> 4:2:2 (replicate rows)
//       4 = 4:1:1 -> 4:2:0 (NVIDIA row-interleaving quirk, see .cu)
NppStatus p3Resample(const Npp8u *const pSrc[3], const int aSrcStep[3], Npp8u *pDst[3], const int aDstStep[3],
                     NppiSize oSizeROI, cudaStream_t stream, int swapSrc, int swapDst, int mode);

// --- planar -> planar Y + interleaved CbCr -------------------------------
// mode: 0 = 4:2:2 -> 4:1:1 packed CbCr, 1 = 4:2:2 -> 4:2:0 packed CbCr,
//       2 = 4:1:1 -> 4:1:1 packed CbCr (P3P2R),
//       3 = 4:1:1 -> 4:2:0 packed CbCr (row-interleaving quirk)
NppStatus p3ToP2(const Npp8u *const pSrc[3], const int aSrcStep[3], Npp8u *pDstY, int nDstYStep, Npp8u *pDstCbCr,
                 int nDstCbCrStep, NppiSize oSizeROI, cudaStream_t stream, int swapSrc, int mode);

// --- planar Y + interleaved 4:1:1 CbCr -> planar 4:2:0 --------------------
NppStatus p2ToP3_420(const Npp8u *pSrcY, int nSrcYStep, const Npp8u *pSrcCbCr, int nSrcCbCrStep, Npp8u *pDst[3],
                     const int aDstStep[3], NppiSize oSizeROI, cudaStream_t stream, int swapDst);

} // namespace c3yuv
} // namespace nppi

#endif // NPPI_C3_YUV_LAYOUT_EXECUTOR_H
